import random, itertools, json, sys, math

def subset_sum_yes(nums, t):
    if t<0: return False
    for r in range(len(nums)+1):
        for comb in itertools.combinations(nums, r):
            if sum(comb)==t:
                return True
    return False

def partition_yes(nums):
    total=sum(nums)
    if total%2: return False
    half=total//2
    for r in range(len(nums)+1):
        for comb in itertools.combinations(nums, r):
            if sum(comb)==half:
                return True
    return False

def reduce_instance(nums, t):
    if t<0:
        return [1,2]
    total=sum(nums)
    if t>total:
        return [1,2]
    extra1=2*t
    extra2=2*total-2*t
    return nums+[extra1, extra2]

for _ in range(1000):
    n=random.randint(0,5)
    nums=[random.randint(0,10) for _ in range(n)]
    total=sum(nums)
    t=random.randint(-5, total+5)
    src=subset_sum_yes(nums,t)
    tgt=partition_yes(reduce_instance(nums,t))
    if src!=tgt:
        print('Mismatch', nums, t, src, tgt)
        sys.exit()
print('All ok')
PY"}

